ion-dm01-av-ch","purpose":"documentation"}],"status":"draft","created_on":"2026-09-05","modified_on":"2026-09-05","version":"DM.01-AV-CH 24 / LV95","responsible_organisation":{"name_de":"Kantonale Stellen der amtlichen Vermessung","websiteUrl":"https://geodienste.ch/services/av"},"classification":null,"contains_personal_data":null,"data_owner_id":null,"data_steward_id":null,"data_custodian_id":null,"domain_id":"5eef2050-ecc3-50a6-9049-45982710ef70","system_id":"50bf0eb7-4c7a-57b2-9f0a-87e25e9e7161","technical_name":"Bodenbedeckung.Gebaeudenummer","row_version":1},{"id":"fe587738-bd0c-5c4d-a13c-d42000569aa3","identifier":"t-av-land-cover-update","name_de":"Nachführung Bodenabdeckung – DM.01","description_de":"Nachführungsinformationen der Bodenbedeckung mit Identifikation, Beschreibung, optionalem Perimeter, Gültigkeit und Datumsangaben.","comment":"INTERLIS-Modellklasse; technischer Name ist kein physischer Datenbanktabellenname. Die Beschreibung ist eine Zusammenfassung. Modellpflicht und Eindeutigkeit gelten für den Datentransfer, nicht automatisch für einen Webdienst.","documentation_links":[{"url":"https://models.geo.admin.ch/V_D/DM.01-AV-CH_LV95_24d_ili1.ili","purpose":"documentation","title_de":"Bodenbedeckung.BBNachfuehrung"},{"url":"https://www.cadastre-manual.admin.ch/de/modelldokumentation-dm01-av-ch","purpose":"documentation"}],"status":"draft","created_on":"2026-09-05","modified_on":"2026-09-05","version":"DM.01-AV-CH 24 / LV95","responsible_organisation":{"name_de":"Kantonale Stellen der amtlichen Vermessung","websiteUrl":"https://geodienste.ch/services/av"},"classification":null,"contains_personal_data":null,"data_owner_id":null,"data_steward_id":null,"data_custodian_id":null,"domain_id":"5eef2050-ecc3-50a6-9049-45982710ef70","system_id":"50bf0eb7-4c7a-57b2-9f0a-87e25e9e7161","technical_name":"Bodenbedeckung.BBNachfuehrung","row_version":1},{"id":"f13e363e-61ce-542e-ab6f-131ae8003082","identifier":"t-av-property","name_de":"Grundstück – DM.01","description_de":"Grundstücksidentifikation und Zustandsangaben im DM.01-AV-CH. Die Art unterscheidet Liegenschaft, selbständige Rechte und Bergwerk. Die Geometrie einer Liegenschaft wird in der zugehörigen Klasse Liegenschaft geführt.","comment":"INTERLIS-Modellklasse; technischer Name ist kein physischer Datenbanktabellenname. Die Beschreibung ist eine Zusammenfassung. Modellpflicht und Eindeutigkeit gelten für den Datentransfer, nicht automatisch für einen Webdienst. EGRID ist im Modell optional. NBIdent und Nummer bilden die deklarierte Identifikation. Keine Eigentümer-, Rechte- oder Grundbuchdaten aus eGRISDM importiert.","documentation_links":[{"url":"https://models.geo.admin.ch/V_D/DM.01-AV-CH_LV95_24d_ili1.ili","purpose":"documentation","title_de":"Liegenschaften.Grundstueck"},{"url":"https://www.cadastre-manual.admin.ch/de/modelldokumentation-dm01-av-ch","purpose":"documentation"},{"url":"https://www.ech.ch/de/ech/ech-0153/1.0","purpose":"documentation"}],"status":"draft","created_on":"2026-09-05","modified_on":"2026-09-05","version":"DM.01-AV-CH 24 / LV95","responsible_organisation":{"name_de":"Kantonale Stellen der amtlichen Vermessung","websiteUrl":"https://geodienste.ch/services/av"},"classification":null,"contains_personal_data":null,"data_owner_id":null,"data_steward_id":null,"data_custodian_id":null,"domain_id":"5eef2050-ecc3-50a6-9049-45982710ef70","system_id":"50bf0eb7-4c7a-57b2-9f0a-87e25e9e7161","technical_name":"Liegenschaften.Grundstueck","row_version":1},{"id":"cbc3c118-63be-5bcf-bce1-5aa1eff1b72e","identifier":"t-av-parcel","name_de":"Liegenschaft – DM.01","description_de":"Geometrie und Flächenmass einer Liegenschaft beziehungsweise eines Teilgrundstücks. Die Referenz Liegenschaft_von verbindet sie mit der Grundstücksidentifikation.","comment":"INTERLIS-Modellklasse; technischer Name ist kein physischer Datenbanktabellenname. Die Beschreibung ist eine Zusammenfassung. Modellpflicht und Eindeutigkeit gelten für den Datentransfer, nicht automatisch für einen Webdienst. Ein Grundstück kann mehrere Teilflächen haben. AREA kann Kreisbögen enthalten; GeoJSON erfordert deren Approximation. Das amtliche Flächenmass ist nicht durch eine neu berechnete Polygonfläche zu ersetzen.","documentation_links":[{"url":"https://models.geo.admin.ch/V_D/DM.01-AV-CH_LV95_24d_ili1.ili","purpose":"documentation","title_de":"Liegenschaften.Liegenschaft"},{"url":"https://www.cadastre-manual.admin.ch/de/modelldokumentation-dm01-av-ch","purpose":"documentation"}],"status":"draft","created_on":"2026-09-05","modified_on":"2026-09-05","version":"DM.01-AV-CH 24 / LV95","responsible_organisation":{"name_de":"Kantonale Stellen der amtlichen Vermessung","websiteUrl":"https://geodienste.ch/services/av"},"classification":null,"contains_personal_data":null,"data_owner_id":null,"data_steward_id":null,"data_custodian_id":null,"domain_id":"5eef2050-ecc3-50a6-9049-45982710ef70","system_id":"50bf0eb7-4c7a-57b2-9f0a-87e25e9e7161","technical_name":"Liegenschaften.Liegenschaft","row_version":1},{"id":"d7accdb0-fde3-5d50-97a9-8203618fe215","identifier":"t-av-property-update","name_de":"Nachführung Liegenschaften – DM.01","description_de":"Nachführungsinformationen der Liegenschaften mit Identifikation, Beschreibung, optionalem Perimeter, Gültigkeit sowie technischem und Grundbucheintrag.","comment":"INTERLIS-Modellklasse; technischer Name ist kein physischer Datenbanktabellenname. Die Beschreibung ist eine Zusammenfassung. Modellpflicht und Eindeutigkeit gelten für den Datentransfer, nicht automatisch für einen Webdienst.","documentation_links":[{"url":"https://models.geo.admin.ch/V_D/DM.01-AV-CH_LV95_24d_ili1.ili","purpose":"documentation","title_de":"Liegenschaften.LSNachfuehrung"},{"url":"https://www.cadastre-manual.admin.ch/de/modelldokumentation-dm01-av-ch","purpose":"documentation"}],"status":"draft","created_on":"2026-09-05","modified_on":"2026-09-05","version":"DM.01-AV-CH 24 / LV95","responsible_organisation":{"name_de":"Kantonale Stellen der amtlichen Vermessung","websiteUrl":"https://geodienste.ch/services/av"},"classification":null,"contains_personal_data":null,"data_owner_id":null,"data_steward_id":null,"data_custodian_id":null,"domain_id":"5eef2050-ecc3-50a6-9049-45982710ef70","system_id":"50bf0eb7-4c7a-57b2-9f0a-87e25e9e7161","technical_name":"Liegenschaften.LSNachfuehrung","row_version":1},{"id":"9a81893b-6d6e-55c4-8d18-2b0b160da439","identifier":"t-av-service-land-cover","name_de":"Bodenabdeckung – geodienste.ch","description_de":"Publizierte Serviceprojektion für Bodenbedeckungsflächen.","comment":"Service-Layer, keine physische Tabelle. Feldnamen und Typen sind im XSD bestätigt; Geometrie ist dort allgemein gml:GeometryPropertyType. Die OGC-API-Beispielabfrage lieferte hier HTTP 403. Wertecodierung und Geometriequalität des Dienstes sind noch zu prüfen; DM.01-Wertelisten werden nicht als bestätigte Servicecodes zugeordnet.","documentation_links":[{"url":"https://geodienste.ch/services/av/info","purpose":"documentation"},{"url":"https://geodienste.ch/db/av_0/deu?REQUEST=DescribeFeatureType&SERVICE=WFS&VERSION=1.1.0","purpose":"documentation"},{"url":"https://geodienste.ch/db/av_0/deu/ogcapi/collections/LCSF?f=json","purpose":"documentation"}],"status":"draft","created_on":"2026-09-05","modified_on":"2026-09-05","version":"24.0.0","responsible_organisation":{"name_de":"Kantonale Stellen der amtlichen Vermessung","websiteUrl":"https://geodienste.ch/services/av"},"classification":null,"contains_personal_data":null,"data_owner_id":null,"data_steward_id":null,"data_custodian_id":null,"domain_id":"5eef2050-ecc3-50a6-9049-45982710ef70","system_id":"50bf0eb7-4c7a-57b2-9f0a-87e25e9e7161","technical_name":"LCSF","row_version":1},{"id":"11179023-fd78-56f7-a297-8dae5eb52e86","identifier":"t-av-service-parcel","name_de":"Liegenschaften – geodienste.ch","description_de":"Publizierte Serviceprojektion für Liegenschaftsflächen mit Grundstücksidentifikation.","comment":"Service-Layer, keine physische Tabelle. Feldnam