  INSERT INTO catalog.data_service (id, identifier, name_de, description_de, documentation_links, status, created_on, modified_on, version, responsible_organisation, classification, contains_personal_data, data_owner_id, data_steward_id, data_custodian_id, domain_id, system_id, service_version, technical_name, access_notes, purpose, row_version, comment)
  SELECT id, identifier, name_de, description_de, documentation_links, status, created_on, modified_on, version, responsible_organisation, classification, contains_personal_data, data_owner_id, data_steward_id, data_custodian_id, domain_id, system_id, service_version, technical_name, access_notes, purpose, row_version, comment FROM jsonb_populate_recordset(NULL::catalog.data_service, '[{"id":"27e22fa5-044b-54b7-b5c9-0c86a30fe85c","identifier":"api-energie","name_de":"Energie-API","description_de":"Zählerstände und Betriebsmesswerte je Gebäude und Periode. Pilotbetrieb.","documentation_links":[{"url":"https://api.bbl.admin.ch/energie/v1/docs","purpose":"documentation"}],"status":"draft","created_on":"2021-09-03","modified_on":"2026-02-03","version":null,"responsible_organisation":{"name_de":"Energiemanagement"},"classification":"internal","contains_personal_data":false,"data_owner_id":"b7ca7c1c-6c76-51ad-9133-5b5ec94b2253","data_steward_id":"375f52f6-6031-5e25-8a73-1fb7d792b4d2","data_custodian_id":null,"domain_id":"9257f4fc-e452-55df-8719-c0894b29cf66","system_id":"38e0e927-5764-54d7-bef8-d7271390af04","service_version":"v0.9","technical_name":null,"access_notes":"intern (eIAM)","purpose":null,"row_version":1},{"id":"47bcb613-759b-5882-9833-9a7239cdba2d","identifier":"api-sap-building","name_de":"SAP RE-FX – Gebäudestammdaten lesen","description_de":"Lesender, synchroner SOAP-Service ZAPI_X4AI_BAPI_RE_BU_GET_DET für die Detaildaten eines Gebäudes aus SAP RE-FX. Die Dokumentation beschreibt 25 Service-Strukturen, darunter Gebäudestammdaten, Adresse, Bemessungen, Partner, Status und kundeneigene Erweiterungen. Kein Massenabruf. Die Katalogbeschreibung bleibt wegen widersprüchlicher Angaben und nicht verifizierter technischer Feldzuordnung im Entwurf; der Service ist in der Quelle als ACTIVE dokumentiert.","comment":"Abweichende Tabellenbezeichnungen zwischen BIT-API-Dokumentation und SAP Help wurden vom Katalogverantwortlichen zur Prüfung im SAP-Frontend vorgemerkt. API-Strukturen, physische Tabellen und architektonische Objekte dürfen bis zur Bestätigung nicht gleichgesetzt werden.","documentation_links":[{"url":"https://confluence.bit.admin.ch/pages/viewpage.action?pageId=1105159761","purpose":"documentation"},{"url":"https://confluence.bit.admin.ch/download/attachments/1105159761/ZAPI_X4AI_BAPI_RE_BU_GET_DET.wsdl","purpose":"documentation"}],"status":"draft","created_on":"2026-09-05","modified_on":"2026-09-05","version":null,"responsible_organisation":{"name_de":"Immobilien"},"classification":null,"contains_personal_data":null,"data_owner_id":null,"data_steward_id":null,"data_custodian_id":null,"domain_id":"5eef2050-ecc3-50a6-9049-45982710ef70","system_id":"cc4f47bb-0fad-573e-9dad-817366482768","service_version":"1.0.0","technical_name":"ZAPI_X4AI_BAPI_RE_BU_GET_DET","access_notes":"Autorisierung durch das Fachamt; für Drittanwendungen Vereinbarung mit dem BIT. Konkrete Berechtigungsobjekte nicht dokumentiert.","purpose":null,"row_version":1},{"id":"4a20e2ff-9fe8-559e-81f9-aa148a511519","identifier":"api-av-wms","name_de":"AV – geodienste.ch WMS","description_de":"Kartendarstellung der Amtlichen Vermessung. Für diesen Katalog sind LCSF (Bodenbedeckung) und RESF (Liegenschaften) relevant.","comment":"GetMap liefert ein Kartenbild. Parcel-Polygone für Berechnungen oder Speicherung über einen Vektordienst beziehen.","documentation_links":[{"url":"https://geodienste.ch/services/av/info","purpose":"documentation"}],"status":"draft","created_on":"2026-09-05","modified_on":"2026-09-05","version":null,"responsible_organisation":{"name_de":"Konferenz der kantonalen Geoinformations- und Katasterstellen (KGK)"},"classification":null,"contains_personal_data":null,"data_owner_id":null,"data_steward_id":null,"data_custodian_id":null,"domain_id":"5eef2050-ecc3-50a6-9049-45982710ef70","system_id":"50bf0eb7-4c7a-57b2-9f0a-87e25e9e7161","service_version":"24.0.0","technical_name":null,"access_notes":"Gemäss kantonaler Verfügbarkeit und Nutzungsbedingungen","purpose":"mapImage","row_version":1},{"id":"192ec7c2-feab-5620-aa3a-2e5d5ff9b258","identifier":"api-av-wfs","name_de":"AV – geodienste.ch WFS","description_de":"Vektorzugriff auf die publizierten AV-Featuretypen; im Katalog auf LCSF und RESF begrenzt.","comment":"Capabilities und Schema geprüft; GetFeature-Datenabruf noch nicht verifiziert. Kantonale Verfügbarkeit und Nutzungsbedingungen prüfen. Paging ist angeboten, laut Capabilities aber nicht transaktionssicher.","documentation_links":[{"url":"https://geodienste.ch/services/av/info","purpose":"documentation"}],"status":"draft","created_on":"2026-09-05","modified_on":"2026-09-05","version":null,"responsible_organisation":{"name_de":"Konferenz der kantonalen Geoinformations- und Katasterstellen (KGK)"},"classification":null,"contains_personal_data":null,"data_owner_id":null,"data_steward_id":null,"data_custodian_id":null,"domain_id":"5eef2050-ecc3-50a6-9049-45982710ef70","system_id":"50bf0eb7-4c7a-57b2-9f0a-87e25e9e7161","service_version":"24.0.0","technical_name":null,"access_notes":"Gemäss kantonaler Verfügbarkeit und Nutzungsbedingungen","purpose":"featureAccess","row_version":1},{"id":"b73c2c90-4587-51e3-bc2f-009e3bc230d1","identifier":"api-av-features","name_de":"AV – geodienste.ch OGC API Features","description_de":"GeoJSON-Zugriff auf AV-Collections. Relevant sind RESF für Liegenschaften und LCSF für Bodenbedeckung.","comment":"Collection-Metadaten geprüft, Beispielabrufe hier HTTP 403. Keine bestätigte flächendeckende Zugänglichkeit. Projektierte Collections RESFPROJ und LCSFPROJ sind getrennt und nicht Teil des importierten Ist-Inventars.","documentation_links":[{"url":"https://geodienste.ch/db/av_0/deu/ogcapi","purpose":"documentation"}],"status":"draft","created_on":"2026-09-05","modified_on":"2026-09-05","version":null,"responsible_organisation":{"name_de":"Konferenz der kantonalen Geoinformations- und Katasterstellen (KGK)"},"classification":null,"contains_personal_data":null,"data_owner_id":null,"data_steward_id":null,"data_custodian_id":null,"domain_id":"5eef2050-ecc3-50a6-9049-45982710ef70","system_id":"50bf0eb7-4c7a-57b2-9f0a-87e25e9e7161","service_version":"24.0.0","technical_name":null,"access_notes":"Gemäss kantonaler Verfügbarkeit und Nutzungsbedingungen","purpose":"featureAccess","row_version":1},{"id":"2cf503d7-3cdb-5548-bfa7-a5a99d0476ff","identifier":"api-av-geoadmin","name_de":"AV – swisstopo GeoAdmin REST","description_de":"Metadaten und Einzelobjekte der AV-Layer ch.swisstopo-vd.amtliche-vermessung und ch.kantone.cadastralwebmap-farbe. Beide lieferten in Stichproben Polygongeometrie.","comment":"Explizit sr=2056 und returnGeometry=true verwenden. Feature-ID ist keine EGRID. SearchServer-Treffer und Bounding Box sind keine vollständige Polygongeometrie. Stichproben bestätigen keine schweizweite Vollständigkeit oder Vermessungsgenauigkeit.","documentation_links":[{"url":"https://docs.geo.admin.ch/access-data/get-features.html","purpose":"documentation"}],"status":"draft","created_on":"2026-09-05","modified_on":"2026-09-05","version":null,"responsible_organisation":{"name_de":"swisstopo"},"classification":null,"contains_personal_data":null,"data_owner_id":null,"data_steward_id":null,"data_custodian_id":null,"domain_id":"5eef2050-ecc3-50a6-9049-45982710ef70","system_id":"50bf0eb7-4c7a-57b2-9f0a-87e25e9e7161","service_version":null,"technical_name":null,"access_notes":"Gemäss kantonaler Verfügbarkeit und Nutzungsbedingungen","purpose":"featureAccess","row_version":1},{"id":"3466df4d-d8e6-5a69-9590-6a4047244faf","identifier":"api-av-geoadmin-wms","name_de":"AV – swisstopo WMS / WMTS","description_de":"Kartendarstellung der Amtlichen Vermessung über die GeoAdmin-Dienste. CadastralWebMap ist als ch.kantone.cadastralwebmap-farbe dokumentiert.","comment":"Rasterdarstellung; keine Vektorextraktion aus Kartenbildern. Für CadastralWebMap empfiehlt die Dokumentation LV95 oder LV03. Der GetFeatures-Zugriff wird separat im REST-Eintrag beschrieben.","documentation_links":[{"url":"https://docs.geo.admin.ch/visualize-data/wmts.html","purpose":"documentation"}],"status":"draft","created_on":"2026-09-05","modified_on":"2026-09-05","version":null,"responsible_organisation":{"name_de":"swisstopo"},"classification":null,"contains_personal_data":null,"data_owner_id":null,"data_steward_id":null,"data_custodian_id":null,"domain_id":"5eef2050-ecc3-50a6-9049-45982710ef70","system_id":"50bf0eb7-4c7a-57b2-9f0a-87e25e9e7161","service_version":null,"technical_name":null,"access_notes":"Gemäss kantonaler Verfügbarkeit und Nutzungsbedingungen","purpose":"mapImage","row_version":1}]'::jsonb);
